CREATE FUNCTION public.validate_basket_quantity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE product public.products; BEGIN SELECT * INTO product FROM public.products WHERE id=NEW.product_id AND published; IF NOT FOUND THEN RAISE EXCEPTION 'Product unavailable'; END IF; IF NEW.quantity<product.min_quantity THEN RAISE EXCEPTION 'Minimum quantity not met'; END IF; IF product.stock IS NOT NULL AND NEW.quantity>product.stock THEN RAISE EXCEPTION 'Quantity exceeds confirmed inventory'; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.validate_basket_quantity() FROM PUBLIC,anon,authenticated; CREATE TRIGGER apex_validate_basket BEFORE INSERT OR UPDATE ON public.cart_items FOR EACH ROW EXECUTE FUNCTION public.validate_basket_quantity();